use core::ffi::{c_void,c_int};unsafe extern "C"{fn memcmp(a:*const c_void,b:*const c_void,n:usize)->c_int;}
#[kani::stub(core::ptr::copy_nonoverlapping,crate::NIZ_KMX::KMX_copy_nonoverlapping)]
#[kani::stub(<[u8]>::copy_from_slice,crate::NIZ_KMX::KMX_copy_from_slice)]
#[kani::stub(alloc::alloc::realloc,crate::NIZ_KMX::KMX_realloc)]
#[kani::proof]
fn certificate(){let mut bytes=[kani::any::<u8>(),kani::any::<u8>(),kani::any::<u8>()];let left=usize::from(kani::any::<u8>());let right=usize::from(kani::any::<u8>());let observer=usize::from(kani::any::<u8>());kani::assume(left<3&&right<3&&observer<3);let a=bytes[left];let b=bytes[right];let frame=bytes[observer];let reply=unsafe{memcmp(bytes.as_ptr().add(left).cast(),bytes.as_ptr().add(right).cast(),1)};bytes[observer]=frame^1;assert!((reply==0)==(a==b));assert!(bytes[observer]==frame);}
